            for tela in [t for t in ('A1-Ponte-Web', 'A2-Ponte-Mobile', 'A4-Sensores-Web', 'A5-Sensores-Mobile') if t in lista]:   # F06: o selo do coletor pela cor (a moldura e, nas telas que têm, o da página)
                total += 1
