            for nome, prob in p4c_conferencias(b, lista):   # P4C: gráfico, Ponte, sensores, ramo simulacao:false e o código
                total += 1
                if prob:
                    falhas.append({'tela': nome, 'tema': 'P4C', 'prob': prob[:8]})
